INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62001041', 62001041, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli IT Fullstack Officer 1 Pengembangan Aplikasi Persiapan pendataan Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 66000000, 'December 2025', 'APBD', 1, 1, '1 orang x 6 bulan', 'Membangun dan merancang sistem frontend dari suatu aplikasi Membuat elemen visual yang responsif dan kompatibel di berbagai perangkat (Desktop, tablet, dan ponsel) Melakukan pengetesan situs Bekerja sama dengan tim back-end untuk memastikan integrasi antarmuka dengan layanan dan API berjalan lancar Berkoordinasi dengan desainer UI/UX untuk menerapkan desain sesuai spesifikasi dan standar pengalaman pengguna Memastikan kode yang dijalankan di situs web dan menentukan apa yang akan dilihat pengguna Memastikan kode berjalan agar setiap perintah pengguna dapat dilakukan Berupaya untuk terus berinovasi dalam hal meningkatkan kualitas dan performa dari sistem aplikasi Memberikan pelatihan terhadap user dan transfer knowledge', 'Pendidikan terakhir D4/S1 jurusan Ilmu Komputer/Sistem Informasi/ Teknik Informatika, Memiliki pengalaman kerja sebagai programmer minimal 3 tahun Memiliki kemampuan bahasa pemograman ReactJS, Bootstrap, HTML 5, CSS 3, dan Java Script Memahami konsep, implementasi dan maintenance relational dan non relational database (Postgres Lebih diutamakan) Memahami konsep Container, REST API, Spring Boot 2, Git Continous Integration dan Deployment menjadi nilai tambah Diutamakan perna