INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62002489', 62002489, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Jasa Konsultansi Penyusunan Dokumen Analisis Kebutuhan dan Pelaporan Pengadaan Barang Operasional Satuan Kerja MWA ICCTF', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 98400000, 'November 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '11 Bulan', 'Ruang lingkup pekerjaan Jasa Konsultan Penyusunan Dokumen Analisis Kebutuhan dan Pelaporan Pengadaan Barang Operasional Satuan Kerja MWA Dana Perwalian Perubahan Iklim Indonesia/ICCTF meliputi: Mengidentifikasi Kebutuhan Barang Melakukan pengumpulan data dan informasi terkait kebutuhan barang operasional ICCTF, rencana pengadaan dan mengidentifikasi kebutuhan barang pada Satuan Kerja MWA ICCTF Subkeluaran: Data dan informasi kebutuhan serta rencana pengadaan barang operasional ICCTF setiap bulan. Pendampingan Pengelolaan Proses Pengadaan Memberikan pendampingan administratif dalam setiap tahapan pengadaan barang operasional sesuai dengan metode pengadaan yang ditetapkan. Subkeluaran: Dokumen administrasi proses pengadaan barang. Pelaporan Pelaksanaan Pengadaan Menyusun laporan pelaksanaan kegiatan pengelolaan dan dokumentasi pengadaan barang. Subkeluaran: Laporan dan pertanggungjawaban pengadaan barang', 'Keluaran dari pekerjaan Jasa Konsultan Penyusunan Dokumen Analisis Kebutuhan dan Pelaporan Pengadaan Barang Operasional Satuan Kerja MWA Dana Perwalian Perubahan Iklim Indonesia/ICCTF terdiri dari: Dokumen Pemetaan Kebutuhan Barang - Dokumen identifikasi dan rekap kebutuhan barang operasional ICCTF TA 2026 (jenis, spesifikasi umum, estimasi nilai) - Konsep kerangka acuan kerja, konsep surat/nota dinas serta minutes of meeting (Notulensi) untuk kegiatan spesifik seperti seminar, workshop, FGD, periode Januari 2026. Dokumen Analisis Pengadaan Langsung - Analisis kesesuaian kebutuhan dengan skema Pengadaan Langsung (< Rp50 juta) dan jadwal pelaksanaan - Realisasi pengadaan langsung barang operasional periode Februari 2026. - Dokumen kelengkapan pembayaran dan arsip transaksi pengadaan barang bulan Februari 2026. - Konsep kerangka acuan kerja, konsep surat/nota dinas serta minutes of meeting (Notulensi) untuk kegiatan spesifik seperti seminar, workshop, FGD, periode Februari 2026. - Pengumpulan informasi harga pasar barang operasional yang akan dibeli pada bulan Maret 2026. - Pelaksanaan pembelian dan penerimaan barang operasional bulan Maret 2026. - Dokumen bukti transaksi keuangan dan dokumentasi fisik barang hasil pengadaan bulan Maret 2026. - Konsep kerangka acuan kerja, konsep surat/nota dinas serta minutes of meeting (Notulensi) untuk kegiatan spesifik seperti seminar, workshop, FGD, periode Maret 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 100890);
