INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63439158', 63439158, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Asisten Kurator Pengembangan Ekspor Daerah', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '. Melakukan kurasi potensi ekspor daerah berdasarkan karakteristik wilayah, struktur ekonomi daerah, dan posisi produk dalam rantai nilai nasional maupun global. 2. Mengidentifikasi isu strategis, tantangan, dan peluang pengembangan ekspor daerah sebagai bahan penguatan substansi dan koordinasi lintas sektor. 3. Menyusun bahan kajian tematik dan telaahan substansi terkait pengembangan ekspor daerah untuk mendukung pengambilan keputusan dan forum koordinasi lintas sektor. 4. Memfasilitasi sinkronisasi dan sinergi antar kementerian/lembaga, pemerintah daerah, dan pemangku kepentingan terkait dalam penguatan pengembangan ekspor daerah. 5. Mengkurasi praktik baik (best practices) dan pembelajaran kebijakan pengembangan ekspor daerah di tingkat nasional dan internasional sebagai referensi penguatan pendekatan pengembangan. 6. Memberikan masukan substansi dan rekomendasi teknokratis non-formulatif terkait penguatan pengembangan ekspor daerah berdasarkan hasil kurasi dan telaahan. 7. Mendukung penguatan perspektif pengembangan ekspor daerah dalam berbagai forum pembahasan lintas sektor dan dialog kebijakan yang difasilitasi oleh Direktorat Industri, Perdagangan, dan Peningkatan Investasi. 8. Melakukan pemantauan umum terhadap dinamika pengembangan ekspor daerah sebagai bahan pengayaan substansi dan koordinasi kebijakan. 9. Menyajikan informasi strategis pengembangan ekspor daerah dalam bentuk ringkasan eksekutif, bahan paparan, dan naskah pendukung.', 'Termin 1 tanggal 2 Februari : Dokumen laporan Pendahuluan pengembangan ekspor ekonomi daerah 2. Termin 2 tanggal 2 Maret : Dokumen kerangka kerja dan metodologi analisis pengembangan ekspor daerah 3. Termin 3 tanggal 1 April : Dokumen pemetaan awal potensi dan komoditas ekspor daerah 4. Termin 4 tanggal 4 Mei : Dokumen identifikasi isu strategis dan tantangan pengembangan ekspor daerah 5. Termin 5 tanggal 1 Juni : Dokumen analisis peluang dan arah pengembangan ekspor daerah 6. Termin 6 tanggal 1 Juli : Dokumen laporan antara pengembangan ekspor ekonomi daerah 7. Termin 7 tanggal 3 Agustus : Dokumen kajian tematik pengembangan ekspor daerah sesuai fokus kebijakan 8. Termin 8 tanggal 1 September : Dokumen Kompilasi praktik baik (best practices) pengembangan ekspor daerah nasional dan internasional 9. Termin 9 tanggal 1 Oktober : Dokumen laporan Akhir pengembangan ekspor ekonomi daerah 10. Termin 10 tanggal 2 November : Dokumen Rekomendasi teknokratis non-formulatif penguatan pengembangan ekspor daerah 11. Termin 11 tanggal 1 Desember : Dokumen ringkasan dinamika dan isu strategis pengembangan ekspor daerah 12. Termin 12 tanggal 21 Desember : Dokumen ringkasan eksekutif, policy brief, atau bahan paparan pendukung koordinasi kebijakan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 101585);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62000946', 62000946, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli IT Backend Officer 3 Pengembangan Aplikasi Persiapan pendataan Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 61050000, 'December 2025', 'APBD', 1, 1, '1 orang x 6 bulan', 'Membangun dan merancang sistem backend dari suatu aplikasi Mendukung siklus pengembangan (konsep, desain, pengujian, rilis, operasional) Merancang struktur database yang optimal untuk penyimpanan dan pengambilan data Melakukan pemeliharaan database, termasuk pencadangan (backup), pengoptimalan, dan migrasi data Memastikan keamanan data melalui enkripsi dan teknik keamanan llainnya Memastikan API dapat menangani permintaan skala besar dengan efisien Mengatasi berbagai bugs dan errors yang terjadi pada aplikasi dari sisi backend Berupaya untuk terus berinovasi dalam hal meningkatkan kualitas dan performa dari sistem aplikasi Melakukan debugging dan fixing terhadap program-program yang masih perlu diperbaiki Membuat script pemrograman yang terstruktur sehingga mempermudah dan dimengerti oleh programmer lain jika ke depannya akan dikembangkan Berkoordinasi dengan front-end developer untuk memastikan integrasi aplikasi berjalan lancar', 'Pendidikan terakhir S1 jurusan Ilmu Komputer/Sistem Informasi/Teknik Informatika Memiliki pengalaman kerja sebagai programmer minimal 2 sampai dengan 14 tahun Memiliki kemampuan bahasa pemograman Java,Swagger, Angular (Mengerti Java Spring Boot lebih diutamakan) Memiliki konsep OOP dan/atau functional programming Memiliki kemampuan bahasa pemograman NodeJS dan PHP, Golang, Bootstrap menjadi nilai tambah Memahami konsep, implementasi dan maintenance relational dan non relational database (Postgres Lebih diutamakan) Memahami konsep Container, REST API, Git Continous Integration dan Deployment menjadi nilai tambah Diutamakan pernah mengikuti pelatihan ISO 27001 Memiliki sertifikat awareness ISO/IEC 27001:2022 Memiliki sertifikat awareness ISO/IEC 20000-1:2013', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 101586);
