INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62002517', 62002517, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli Data Analyst Persiapan pendataan Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 50875000, 'December 2025', 'APBD', 1, 1, '1 orang x 6 bulan', 'Mengembangkan analisa data berdasarkan kebutuhan informasi yang dibutuhkan Mengembangkan instrumen monitoring dan evaluasi pendataan keluarga satu pintu Menyusun analisa, identifikasi data metodologi analisis, dan memaparkan analisis terhadap suatu isu yang ada Mengembangkan rencana tabulasi data berdasarkan hasil assestment kebutuhan informasi Membuat paparan/laporan/rekomendasi/policy brief dari hasil analisa data dalam pengambilan kebijkakan Mengembangkan modul pelatihan pendataan keluarga satu pintu Berperan aktif dalam melakukan pendampingan dan pelatihan terhadap kader dasawisma Melakukan pendampingan terkait sosialisasi pendataan keluarga satu pintu', 'Pendidikan terakhir S2 Jurusan Statistik/ Ilmu Statistik terapan lainya (Ekonometri, Psikometri,Biostatistik, Epidemilogi) IPK min 3.0 (PTS) /2.75 (PTN); Memiliki pengalaman kerja minimal 1 tahun di bidang penelitian Memiliki pengalaman mengerjakan manajemen data Memiliki logika yang kuat dalam menganalisa data dan menyajikannya secata tepat Menguasai pengetahuan dalam mengunakan aplikasi statistik (SPSS, STATA, SAS, dll) Menguasai pengetahuan dalam mengunakan aplikasi geospasial (Arch GIS, Quantum GIS, gVISG, dll) Memahami konsep database Mampu melakukan pembuatan jurnal ilmiah Memiliki kemampuan menjelaskan analisis Diutamakan pernah mengikuti pelatihan ISO 27001', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 101598);
