INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62023954', 62023954, 'analyze_legacy', 'Kota Bekasi', 'kabkota', 'Dinas Lingkungan Hidup', 'PJLP PETUGAS PENGOLAHAN SAMPAH 205', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Bekasi (Kota)', 48074400, 'December 2025', 'APBD', 1, 1, '1 Paket', 'Petugas Pengolahan Sampah adalah individu atau bagian dari suatu badan usaha/unit pelaksana teknis pemerintah yang bertanggung jawab untuk melaksanakan kegiatan operasional dan/atau teknis penunjang dalam pengelolaan sampah secara sistematis, menyeluruh, dan berkesinambungan.', 'Petugas Pengolahan Sampah adalah individu atau bagian dari suatu badan usaha/unit pelaksana teknis pemerintah yang bertanggung jawab untuk melaksanakan kegiatan operasional dan/atau teknis penunjang dalam pengelolaan sampah secara sistematis, menyeluruh, dan berkesinambungan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 102913);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62002539', 62002539, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Jasa Konsultansi Manajemen Persediaan dan Asset Satuan Kerja MWA ICCTF', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 98400000, 'November 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '11 Bulan', 'Ruang Lingkup Jasa Konsultansi Manajemen Persediaan dan Asset Satuan Kerja ICCTF meliputi: 1. Analisis Kondisi Eksisting - Review kebijakan, pedoman, dan SOP pengelolaan persediaan dan aset ICCTF - Evaluasi sistem pencatatan, inventarisasi, dan pelaporan persediaan dan aset - Analisis kesesuaian dengan peraturan perundang-undangan, ketentuan internal ICCTF, dan persyaratan donor - Identifikasi permasalahan, risiko, dan kesenjangan (gap) dalam pengelolaan persediaan dan aset 2. Penguatan Sistem Manajemen Persediaan - Evaluasi perencanaan kebutuhan dan pengadaan persediaan - Penyempurnaan mekanisme penerimaan, penyimpanan, distribusi, dan pengendalian persediaan - Penyusunan standar pencatatan dan pelaporan persediaan - Rekomendasi pengendalian internal untuk meminimalkan risiko kehilangan dan ketidaksesuaian 3. Penguatan Sistem Manajemen Aset - Inventarisasi dan verifikasi data aset ICCTF - Evaluasi pengelolaan aset tetap dan aset lainnya (penggunaan, pemeliharaan, dan penghapusan) - Penyusunan klasifikasi, penandaan (labeling), dan pengkodean aset Penyusunan mekanisme monitoring dan pelaporan aset 4. Penyusunan dan Penyempurnaan Dokumen - Penyusunan atau revisi kebijakan pengelolaan persediaan dan aset - Penyusunan atau penyempurnaan SOP manajemen persediaan dan aset - Penyusunan format standar pencatatan, inventaris, dan laporan persediaan serta aset 5. Pendampingan dan Transfer Pengetahuan - Pendampingan implementasi rekomendasi pengelolaan persediaan dan aset - Sosialisasi dan bimbingan teknis kepada pegawai terkait - Transfer pengetahuan untuk memastikan keberlanjutan sistem', 'Keluaran dari pekerjaan Jasa Konsultan Manajemen Persediaan dan Asset ICCTF Satuan Kerja MWA Dana Perwalian Perubahan Iklim Indonesia/ICCTF terdiri dari: Usulan Rencana kerja pelaksanaan penguatan manajemen persediaan dan aset TA 2026. Metodologi inventarisasi, verifikasi, dan rekonsiliasi aset dan persediaan. Daftar awal objek persediaan dan inventaris (preliminary listing) sebagai dasar inventarisasi Draft SOP manajemen persediaan dan aset. Laporan Hasil inventarisasi fisik tahap I. Pengumpulan dan penelaahan dokumen pendukung aset dan persediaan. Update database inventaris persediaan dan aset tahap awal. Final SOP manajemen persediaan dan aset. Finalisasi dokumen baseline persediaan dan aset. Database persediaan dan aset baseline yang telah diverifikasi. Laporan hasil Identifikasi tata kelola dan pengendalian internal pengelolaan persediaan dan aset. Berita acara inventarisasi awal. Flowchart/alur proses pengelolaan persediaan dan aset. Template dan instrumen pendukung persediaan dan aset (KIB, BA, dan Formulir). Rekonsiliasi persediaan dan aset Semester I. Berita acara rekonsiliasi persedaiaan dan aset Semester I.Semester I. Database persediaan dan aset terbarui Semester I. Hasil monitoring implementasi SOP manajemen persediaan dan aset.. Pemutakhiran database persediaan dan aset atas mutasi dan pengadaan baru. Analisis permasalahan dan risiko pengelolaan persediaan dan aset. Rekomendasi perbaikan operasional pengelolaan persediaan dan aset Dokumen rekomendasi penataan dan optimalisasi persediaan dan aset. Update database persediaan dan aset berdasarkan rekomendasi optimalisasi. Inventarisasi fisik akhir tahun Persiapan rekonsiliasi akhir tahun persediaan dan aset. Update database persediaan dan aset berdasarkan rekomendasi optimalisasi Dokumen kesiapan audit persediaan dan aset. Rekonsiliasi akhir persediaan dan aset TA 2026. Dokumen kesiapan audit persediaan dan aset. Database persediaan dan aset final TA 2026. Laporan akhir pelaksanaan jasa konsultan. Ringkasan capaian output bulanan dan tahunan. Rekomendasi keberlanjutan pengelolaan persediaan dan aset Satker ICCTF.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 102914);
