INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63501216', 63501216, 'analyze_legacy', 'Kab. Pekalongan', 'kabkota', 'Rumah Sakit Umum Daerah Kraton', 'Pembangunan Ruang Cytotoxic Drugs Safety Cabinet', 'Pekerjaan Konstruksi', 'E-Purchasing', 'Jawa Tengah, Pekalongan (Kab.)', 1200000000, 'June 2026', 'APBD', 1, 1, '1 Paket', 'Pembangunan Ruang Model Cytotixic Drugs Safety Cabinet dengan model MEDKIT-CTX-LTE.01 mengacu pada unit Modular Cleanroom portabel atau prefabrikasi yang dirancang khusus untuk penanganan obat sitotoksik (kemoterapi) dengan luas area ±50 m²', 'Berikut adalah spesifikasi teknis untuk ruangan tersebut berdasarkan standar ruang penanganan sitotoksik dan tata udara rumah sakit: 1. Arsitektur & Dimensi Luas Total: ±50 M² (biasanya dibagi menjadi beberapa zona: Anteroom, Changing Room, dan Main Prep Room). Dinding & Plafon: Panel Sandwich (EP atau PIR) dengan ketebalan standar 50mm, permukaan antibacterial yang mudah dibersihkan dan tahan terhadap bahan kimia. Lantai: Vinyl kelas medis (homogeneous vinyl) dengan sistem coving (lengkungan di sudut pertemuan lantai-dinding) untuk mencegah penumpukan debu. Pintu: Pintu kedap udara dengan sistem interlock elektronik untuk menjaga tekanan udara. 2. Sistem Tata Udara (HVAC) & Cleanroom Standar Kebersihan: ISO Class 7 atau ISO Class 8 (Kelas 10.000 atau 100.000). Tekanan Udara: Tekanan Negatif pada ruang peracikan utama untuk mencegah paparan obat berbahaya ke area luar. Filtrasi: Dilengkapi dengan filter HEPA (High Efficiency Particulate Air) dengan efisiensi ≥99,99%. Air Change Per Hour (ACH): Minimal 20–30 kali pergantian udara per jam. Kontrol Suhu & Kelembaban: Suhu dijaga pada 20°C ± 2°C dengan kelembaban 45% – 60%. 3. Peralatan Utama (Integrasi MEDKIT-CTX) Cytotoxic Safety Cabinet (CSC): Biasanya model CTX-1100 atau tipe Class II Type B2 (100% exhaust) yang membuang udara langsung ke luar gedung setelah melalui filter. Pass Box: Kotak transfer barang antar ruang dengan sistem interlock dan lampu UV sterilisasi. Sistem Monitoring (LTE.01): Sesuai kode model "LTE", unit ini biasanya dilengkapi pemantauan suhu, kelembaban, dan tekanan secara real-time berbasis IoT/Konektivitas seluler (LTE) untuk pelaporan otomatis ke server pusat. 4. Sistem Pendukung & K3 Lampu: Pencahayaan LED khusus cleanroom (rata dengan plafon/flush mount). Waste Management: Tempat sampah khusus limbah sitotoksik berlabel ungu. Emergency Unit: Dilengkapi dengan Emergency Eye Wash dan Spill Kit sitotoksik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 103269);
