INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62002613', 62002613, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Pengelolaan Layanan Perkantoran dan Administrasi PPK Satuan Kerja MWA ICCTF', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 115285651, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '11 Bulan', 'Ruang lingkup pekerjaan Tenaga Pengelolaan Layanan Perkantoran dan Administrasi PPK Satker MWA ICCTF meliputi: 1. Melakukan administrasi pengelolaan data anggaran sesuai dengan peraturan perundang-undangan yang berlaku, meliputi pengumpulan dan pengkoreksian berkas, pra-verifikasi berkas, klarifikasi dengan direktorat terkait, dan penyiapan SPP dan berkas pendukung. 2. Mengolah data pada aplikasi pelaporan pemerintahan, antara lain SIMBAR, SAKTI Modul ADMIN, OMSPAN, SISTRANAS, SRIKANDI, dan MON SAKTI. 3. Mengolah data untuk rekonsiliasi BPJS Ketenagakerjaan, Persediaan, BMN, BAR Rek. Koran, dan Satker ICCTF. 4. Melakukan administrasi persuratan, pengadaan Tim PPK, persediaan, kontrak/SPK, pendataan ICCTF, administrasi layanan administrasi sekretariat PPK dan rekonsiliasi anggaran ICCTF. 5. Melakukan koordinasi dengan para koordinator kegiatan dan staf Sekretariat PPK lainnya dalam administrasi pengelolaan data dan anggaran ICCTF. 6. Melakukan koordinasi dengan pihak terkait, antara lain Bagian Perbendaharaan dan Keuangan dan Bagian Program dan Anggaran, terkait dengan administrasi pengelolaan data anggaran. 7. Memahami peraturan-peraturan terkait pengelolaan APBN, terutama terkait Rupiah Murni dan Hibah Rekening Khusus. 8. Melakukan penginputan pengajuan dari pihak Satker MWA ICCTF pada aplikasi pertanggungjawaban, serta berkoordinasi dengan Bagian Perbendaharaan dan Keuangan Bappenas terkait pengajuan tersebut. 9. Bertanggung jawab terhadap dukungan administrasi untuk kelancaran pelaksanaan kegiatan Satker Majelis Wali Amanat Dana Perwalian Perubahan Iklim Indonesia/ICCTF. 10. Bertanggung jawab atas terpenuhinya administrasi kebutuhan dalam hal pelaporan keuangan Tahun Anggaran Berjalan.', 'Keluaran Tenaga Pengelolaan Layanan Perkantoran dan Administrasi PPK Satker MWA ICCTF meliputi: Laporan Termin 1, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) Laporan Termin 2, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) - Laporan rekonsiliasi BPJS Ketenagakerjaan, Persediaan, BMN, BAR Rek. Koran Satker ICCTF - Laporan koordinasi administrasi pengelolaan data anggaran - Laporan Triwulan 1 - Draf Laporan Triwulanan BMN Laporan Termin 3, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) Laporan Termin 4, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) Laporan Termin 5, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) - Laporan rekonsiliasi BPJS Ketenagakerjaan, Persediaan, BMN, BAR Rek. Koran Satker ICCTF - Laporan koordinasi administrasi pengelolaan data anggaran - Laporan Triwulan 2 - Draf Laporan Triwulanan BMN Laporan Termin 6, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) Laporan Termin 7, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) Laporan Termin 8, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) - Laporan rekonsiliasi BPJS Ketenagakerjaan, Persediaan, BMN, BAR Rek. Koran Satker ICCTF - Laporan koordinasi administrasi pengelolaan data anggaran - Laporan Triwulan 3 - Draf Laporan Triwulanan BMN Laporan Termin 9, memuat: - Laporan bulanan atas arsip persuratan - Laporan pemanfaaatan Aplikasi Pelaporan Pemerintahan (SIMBAR, SAKTI Modul Admin, OMSPAN, Sistranas) Laporan Termin 10, memuat: - Laporan akhir tahun atas arsip persuratan - Laporan akhir rekonsiliasi BPJS Ketenagakerjaan, Persediaan, BMN, BAR Rek. Koran Satker ICCTF - Laporan Akhir Pengelolaan BMN', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 103363);
