INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62002365', 62002365, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Jasa Konsultansi Pengembangan Visual dan Konten Digital Satuan Kerja MWA ICCTF', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 107068500, 'November 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '11 Bulan', 'Ruang Lingkup pekerjaan Konsultan individu Tenaga Konsultan Pengembangan Visual dan Konten Digital meliputi: Berkoordinasi dan berkomunikasi dengan bagian program dalam mensinergikan program & kegiatan publikasi, kampanye, dan komunikasi lembaga ICCTF guna mengarusutamakan isu perubahan iklim, serta upaya meningkatkan kesadaran masyarakat akan perubahan perilaku yang ramah lingkungan. Mengimplementasikan kegiatan penjangkauan komunikasi (outreach), publikasi dan mendukung kampanye fundraising ICCTF sesuai dengan strategi komunikasi lembaga termasuk peningkatan kesadaran akan ICCTF dengan pemerintah pusat dan provinsi, masyarakat internasional khususnya donor dan mitra pembangunan, masyarakat sipil dan organisasi profesi, komunitas akademis, media dan masyarakat pada umumnya. Menyusun draf konten untuk keperluan publikasi lembaga, termasuk di dalamnya mendesain factsheet program dan kegiatan, laporan tahunan, poster, brosur, presentasi. Mengembangkan dan mengelola konten media sosial digital Lembaga untuk mempromosikan ICCTF dan misinya (baik dalam media cetak, berbasis web, media sosial, dll), dengan lingkup sebagai berikut: Membuat, mengembangkan ide kreatif, merencanakan konten dan mengelola Youtube. Membuat, mengembangkan ide kreatif, merencanakan konten dan mengelola akun media sosial Lembaga termasuk bertanggung jawab atas komentar dan pesan langsung di media sosial. Bertanggung jawab untuk membuat copywriting untuk konten Youtube dan media sosial lainnya. Mengembangkan video story-board untuk konten Youtube dan sosial media. Menyusun draf konten untuk keperluan website serta berkoordinasi dengan Bagian IT dalam hal memelihara dan memperbarui secara teratur situs web ICCTF (berita, dokumen dan publikasi). Mengarahkan dan berkolaborasi dengan Videographer untuk produksi video. Mengelola, membuat, dan mempublikasikan konten orisinal dan berkualitas tinggi. Memberikan masukan untuk perbaikan Standar Prosedur Operasional ICCTF, strategi komunikasi, strategi penggalangan dana, rencana bisnis, dan dokumen pengembangan kelembagaan lainnya. Melaksanakan tugas lainnya yang ditugaskan atasan langsung maupun tidak langsung.', 'Keluaran jasa Konsultan Pengembangan Visual dan Konten Digital adalah • Pemahaman awal terhadap kebutuhan ICCTF melalui koordinasi dengan tim substansi untuk mengidentifikasi prioritas dan kebutuhan komunikasi visual. • Sinkronisasi agenda program & kegiatan ICCTF • Pelaksanaan permintaan desain dan pembaruan konten ad-hoc atau sesuai dengan perencanaan. • Publikasi konten media sosial. • Desain fact sheet, materi, atau cover presentasi (PPT). • Dokumentasi kegiatan sesuai penugasan. • Koordinasi rutin pelaksanaan publikasi & komunikasi ICCTF • Pelaksanaan permintaan desain dan pembaruan konten ad-hoc atau sesuai dengan perencanaan. • Updating/publikasi konten media sosial • Dokumentasi kegiatan sesuai penugasan. • Rekapitulasi konten & kegiatan 2026 serta evaluasi efektivitas media/visual. • Membuat Desain Kalender 2027 • Pelaksanaan permintaan desain dan pembaruan konten ad-hoc atau sesuai dengan perencanaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 103738);
