INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62002420', 62002420, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Jasa Konsultansi Pengembangan Desain dan Perumusan Proyek Satuan Kerja MWA ICCTF', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 51480000, 'November 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '5 Bulan', 'Ruang lingkup pekerjaan Jasa Konsultan Pengembangan Desain dan Perumusan Proyek MWA ICCTF TA 2026 mencakup penyediaan keahlian teknis dalam perancangan, penelaahan substansi, serta penyusunan draf dokumen strategis pada berbagai tahapan pengembangan program. Pelaksanaan pekerjaan dilakukan dengan pendekatan berbasis keluaran (output-based contract) yang berfokus pada akurasi data, kualitas rancangan operasional, dan kepatuhan terhadap standar mitra pembangunan internasional., serta dukungan strategis terhadap transformasi kelembagaan ICCTF, di bawah koordinasi dan arahan Pimpinan ICCTF serta sesuai dengan ketentuan peraturan perundang-undangan dan standar mitra pembangunan internasional. Persiapan Teknis Proyek Melakukan penelaahan kritis dan sinkronisasi terhadap draf Project Appraisal Document (PAD) proyek BLP World Bank. Menyusun dan merumuskan draf dalam Project Operational Manual (POM) proyek BLP dan sinkronisasi substantif kolaborasi intensif bersama mitra World Bank dan tim teknis dari Direktorat Pangan dan Pertanian. Menyusun draf awProject Timeline proyek BGF, mencakup tahapan dari persiapan hingga transisi implementasi. Menyusun draf Annual Working Plan proyek BGF yang mendetailkan aktivitas prioritas, target antara, serta kebutuhan sumber daya teknis. Melakukan pemetaan dependensi antar-kegiatan dan analisis risiko operasional pada fase awal pengembangan proyek dekarbonisasi biogas. Menyiapkan draf Kerangka Acuan Kerja (KAK) untuk komponen kegiatan di bawah kerangka kerja proyek BGF. Menyusun draf bahan paparan teknis yang memuat argumen strategis dan konsep inovasi produksi padi untuk keperluan diskusi persiapan hibah dengan KOICA. Menyiapkan draf Position Paper atau dokumen ringkasan teknis (Technical Briefing) untuk keperluan persiapan hibah dengan KOICA. Melakukan penelaahan awal terhadap draf klausul teknis atau persyaratan hibah yang diusulkan oleh KOICA sebagai bahan pertimbangan dalam proses negosiasi. Menyiapkan catatan teknis (technical notes) dan draf tanggapan atas masukan mitra donor terkait progres finalisasi dokumen rancangan proyek. Menyiapkan draf bahan tayang (PPT) terkait persiapan proyek apabila dibutuhkan. Pengembangan Project Pipeline Melakukan identifikasi, riset awal, dan penyusunan data baseline untuk pengembangan ide-ide proyek baru yang potensial masuk ke dalam project pipeline organisasi. Mengelola dan memperbarui database portofolio proyek secara rutin untuk memastikan ketersediaan data status pengembangan proyek yang akurat dan terkini. Dukungan Strategis Transformasi ICCTF menuju ID-Fund Memberikan masukan substansi terkait pengembangan proyek dan menyusun draf usulan dalam dokumen persyaratan BLU Transformasi ICCTF Melakukan koordinasi teknis dalam proses harmonisasi substansi rancangan Kepmen ID-Fund bersama Biro Hukum dan unit kerja terkait di Bappenas Menyiapkan draf paparan strategis terkait poin-poin kunci dalam Transformasi ICCTF sebagai bahan masukan bagi pimpinan dalam rapat-rapat pengambilan keputusan di tingkat kementerian.', 'Keluaran dari pekerjaan Jasa Konsultan Pengembangan Desain dan Perumusan Proyek ICCTF TA 2026 sebagai berikut: 1. Persiapan Teknis Proyek Laporan ringkas hasil koordinasi teknis bersama Direktorat Pangan Pertanian dan World Bank terkait proyek BLP Draf Project Timeline proyek BGF Kumpulan draf materi presentasi teknis (PPT) untuk persiapan hibah KOICA. 2. Pengembangan Project Pipeline Pembaruan database pipeline proyek periode I 3. Transformasi ID Fund Dokumen draf catatan usulan-usulan rapat terkait ID Fund Kumpulan draf bahan tayang (PPT) Transformasi ID-Fund 1. Persiapan Teknis Proyek Draf hasil revisi PAD proyek BLP Draf Annual Working Plan (AWP) proyek BGF TA 2026 Draf Briefing Notes pengembangan Rice Innovation Center (KOICA). 2. Pengembangan Project Pipeline Pembaruan database pipeline proyek periode II 3. Transformasi ID Fund Dokumen draf catatan usulan-usulan rapat terkait ID Fund Kumpulan draf bahan tayang (PPT) Transformasi ID-Fund 1. Persiapan Teknis Proyek Draf hasil revisi dokumen Project Operational Manual (POM) proyek BLP Dokumen draf KAK proyek BGF Draf rancangan awal konsep teknis (Pre-concept Paper) proyek KOICA. 2. Pengembangan Project Pipeline Pembaruan database pipeline proyek periode III 3. Transformasi ID Fund Dokumen draf catatan usulan-usulan rapat terkait ID Fund Kumpulan draf bahan tayang (PPT) Transformasi ID-Fund Catatan teknis hasil pembahasan dan harmonisasi draf Kepmen ID-Fund Draf usulan substansi terkait pengembangan proyek kepada dokumen persyaratan BLU Transformasi ICCTF', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 104124);
