INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62027490', 62027490, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK KABUPATEN - KEP.SERIBU', 'Teknisi Jaringan Senior Kominfotik', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Adm. Kepulauan Seribu (Kab.)', 104074425, 'December 2025', 'APBD', 1, 1, '1 orang x 12 bulan', 'Teknisi Jaringan Senior Kominfotik Ruang lingkup Pekerjaan Pengadaan PJLP Layanan Jaringan Intra Pemerintah, meliputi proses pengadaan Petugas Informasi dan Teknologi - Teknisi Jaringan Senior Kominfotik yang tugasnya antara lain: a.Melakukan monitoring dan pemeliharaan sistem komputer dan jaringan. b.Melakukan Monitoring dan pendampingan teknis operasional jaringan komunikasi. c.Melakukan troubleshooting sistem dan masalah jaringan serta mendiagnosa dan memecahkan masalah hardware / kesalahan perangkat lunak. d.Melakukan konfigurasi perangkat jaringan dan multimedia. e.Melakukan pengaturan account pengguna baru atau profil dan berurusan dengan masalah password. f.Melakukan Instalasi Jaringan : crimping, splicing dan testing. g.Melakukan pemeriksaan keamanan kelistrikan pada peralatan komputer. h.Menerima konsultasi permasalahan IT melalui serangkaian tindakan, baik tatap muka atau melalui telepon. i. Melakukan pengecekan dan pemeriksaan hasil Instalasi komputer/ Jaringan j. Memiliki rasa tanggung jawab dan kepedulian yang tinggi dalam menggunakan barang milik daerah ( BMD ) k.Pengumpulan laporan hasil pekerjaan setiap bulan.', 'Teknisi Jaringan Senior Kominfotik Persyaratan kualifikasi teknis untuk penyedia jasa, meliputi: 1.Pendidikan minimal S1 jurusan bidang komputer/informatika; 2.Memiliki keahlian dalam bidang IT/ komputer/ jaringan internet; 3.Pengalaman kerja minimal 5 tahun; 4.Memiliki pengetahuan dasar perangkat jaringan Cisco/Mikrotik/Ubiquiti; 5.Memiliki kemampuan teknis tingkat lanjut penggunaan perangkat jaringan dan perangkat multimedia; 6.Memiliki pengalaman kerja di lingkungan pemerintahan; 7.Mempunyai kemampuan komunikasi yang baik; 8.Memiliki sertifikat pelatihan komputer/jaringan; 9.Memiliki Surat Izin Mengemudi yang masih berlaku yaitu SIM C (nilai tambah apabila juga memiliki SIM A); 10.Memiliki kendaraan bermotor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 107751);
