INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62025980', 62025980, 'analyze_legacy', 'Kementerian Agama', 'central', 'STAHN MPU KUTURAN SINGARAJA 418477', 'Pengawasan Kelanjutan Tahap II  Konstruksi Gedung Pelayanan Akademik Dan Kemahasiswaan Kampus Kresna', 'Jasa Konsultansi', 'Seleksi', 'Bali, Buleleng (Kab.)', 1209658000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Lingkup kewenangan Penyedia Jasa Pekerjaan Pengawasan Kelanjutan Tahap II Konstruksi Gedung Pelayanan Akademik Dan Kemahasiswaan Kampus Kresna pada pelaksanaan pengawasan adalah sebagai berikut : Tanggung Jawab Penyedia 1. Melaksanakan pengawasan pekerjaan di lapangan, sehingga tetap terlaksana dengan baik sesuai dengan rencana kerja dan syarat/spesifikasi teknis pelaksanaan pekerjaan; 2. Menampung persoalan terkait pelaksanaan konstruksi di lapangan dan menyampaikan serta memberikan rekomendasi opsi solutif kepada PPK; dan 3. Meneliti kebenaran atau membandingkan laporan progres pekerjaan yang di klaim/dinyatakan oleh pelaksana pekerjaan dengan yang diperoleh dari laporan tenaga konsultan supervisi di lapangan. Wewenang Penyedia 1. Memberikan peringatan dan teguran tertulis kepada pihak pelaksana pekerjaan jika terjadi penyimpangan terhadap dokumen kontrak; 2. Meneliti dan memberikan persetujuan pada gambar pelaksanaan (shop drawing) yang diajukan oleh kontraktor sebelum dilaksanakan; 3. Merekomendasikan kepada pengguna jasa untuk menghentikan pelaksanaan pekerjaan sementara jika peleksanaan pekerjaan tidak memperhatikan peringatan yang diberikan; 4. Memberikan masukan pendapat teknis tentang permintaan tambah kurang pekerjaan yang diajukan oleh pelaksana fisik yang dapat mempengaruhi biaya dan waktu pekerjaan serta berpengaruh pada ketentuan kontrak; 5. Mengusulkan perubahan jika terjadi ketidaksesuaian dengan kondisi di lapangan; 6. Mengkoreksi pekerjaan yang dilaksanakan oleh pelaksana pekerjaan, termasuk pekerjaan fisik konstruksi yang telah dilaksanakan agar sesuai dengan kontrak kerja yang disepakati; dan 7. Merekomendasikan kepada PPK untuk menolak material dan peralatan konstruksi yang tidak sesuai spesifikasi.', 'Lingkup kewenangan Penyedia Jasa Pekerjaan Pengawasan Kelanjutan Tahap II Konstruksi Gedung Pelayanan Akademik Dan Kemahasiswaan Kampus Kresna pada pelaksanaan pengawasan adalah sebagai berikut : Tanggung Jawab Penyedia 1. Melaksanakan pengawasan pekerjaan di lapangan, sehingga tetap terlaksana dengan baik sesuai dengan rencana kerja dan syarat/spesifikasi teknis pelaksanaan pekerjaan; 2. Menampung persoalan terkait pelaksanaan konstruksi di lapangan dan menyampaikan serta memberikan rekomendasi opsi solutif kepada PPK; dan 3. Meneliti kebenaran atau membandingkan laporan progres pekerjaan yang di klaim/dinyatakan oleh pelaksana pekerjaan dengan yang diperoleh dari laporan tenaga konsultan supervisi di lapangan. Wewenang Penyedia 1. Memberikan peringatan dan teguran tertulis kepada pihak pelaksana pekerjaan jika terjadi penyimpangan terhadap dokumen kontrak; 2. Meneliti dan memberikan persetujuan pada gambar pelaksanaan (shop drawing) yang diajukan oleh kontraktor sebelum dilaksanakan; 3. Merekomendasikan kepada pengguna jasa untuk menghentikan pelaksanaan pekerjaan sementara jika peleksanaan pekerjaan tidak memperhatikan peringatan yang diberikan; 4. Memberikan masukan pendapat teknis tentang permintaan tambah kurang pekerjaan yang diajukan oleh pelaksana fisik yang dapat mempengaruhi biaya dan waktu pekerjaan serta berpengaruh pada ketentuan kontrak; 5. Mengusulkan perubahan jika terjadi ketidaksesuaian dengan kondisi di lapangan; 6. Mengkoreksi pekerjaan yang dilaksanakan oleh pelaksana pekerjaan, termasuk pekerjaan fisik konstruksi yang telah dilaksanakan agar sesuai dengan kontrak kerja yang disepakati; dan 7. Merekomendasikan kepada PPK untuk menolak material dan peralatan konstruksi yang tidak sesuai spesifikasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 107922);
