INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62006844', 62006844, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'RUTAN KELAS II B MUNTOK', 'Pengadaan Bahan Makanan Tahanan, Anak, Narapidana, Anak Binaan dan Anak Bawaan pada Rutan Kelas IIB Muntok - Kepulauan Bangka Belitung Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'Kep. Bangka Belitung, Bangka Barat (Kab.)', 2283440000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Bahan Makanan Tahanan, Anak, Narapidana, Anak Binaan dan Anak Bawaan pada Rutan Kelas IIB Muntok - Kepulauan Bangka Belitung Tahun Anggaran 2026', 'PESIFIKASI TEKNIS 1. Beras : Kualitas medium, bersih, tidak apek, tidak banyak gabah, tidak terdapat kerikil, tidak terdapat kutu beras. 2. Ubi Jalar setara Ketela (singkong) 3. Daging sapi/kerbau 4. Ayam Broiler/Ras 5. Ikan Kering 6. Ikan segar 7. Telur ayam Negeri (Ras) 8. Tempe 9. Tahu 10. Kacang-kacangan (kacang tanah/kacang merah/lainnya) 11. Kacang Hijau 12. Kelapa Daging 13. Sayuran segar 14. Buah-buahana 15. Gula Kelapa/Aren 16. Gula Pasir 17. Minyakgoreng 18. Bumbu Dapur 19. Racikan Sambel 20. Garam dapur 21. Kecap 22. Gas 23. Air Segar dan bersih. Segar, sedikit urat/lemak, tidak berlendir, tidak mengandung bahan pengawet, kondisi daging tidak boleh lebih lama dari satu hari sesudah pemotongan. Bersih, segar, muda, berat minimum 1 kg/ekor, tanpa isi, tidak suntikair, kulit belum keras, (halal). Bisa berupa ikan kering asin atau ikan kering tawar dengan spesifikasikering dan bersih. Segar, berkilat, kenyal, tidak hancur, utuh tidak berformalin. Kulit bersih, tidak busuk, tidak retak, dalam 1 Kg berisi +- 16 butir. Berkualitas baik, segar dan tidak busuk. Warna putih/kuning, segar, bersih, murni padat, tidak hancur, mutu baik, tidak bergaram, tanpa formalin, kenyal, berat minimal 50 gram. Kering, bersih, tua, tidak hancur, tidak berjamur, tidak tengik. Kering, bersih, tua, tidak berkutu. a. Kelapa sedang (banyak santan), segar, tidak busuk dan telah terkupas. b. Tidak boleh diganti kopraa. Harus yang sehat, bermutu baik dan segar serta mengandung zat makanan seperti kobis, sawi, wortel, labu, terong, daun melinjo, kacang panjang, kangkung, ketimun dan lain-lain. b. Harus beganti-ganti setiap hari dan merupakan campuran sayuran yang beratnya berimbang sesuai daftar menu. c. Tidak termasuk bagian sayur-sayuran yang tidak dapat dimakan. a. Jeruk Manis : segar, manis,tidak busuk, kulit kuning tua, matang pohon (Kg). b. Pepaya : segar, masak, tidak busuk (Kg) c. Pisang : tua, masak dan tidak busuk (Bh) Kering, kuning, tidak bersampah, kualitas super, tidak keropos, tanpa campuran. Kering, bersih, murni, dalam negeri/local, tidak hancur, tidak menggumpal, tidak mangkak. Harus bersih dan baik Terdiri dari bermacam-macam rempah seperti: cabe, bawang merah, bawang putih, ketumbar, merica, kemiri, jintan, kunyit, jahe, salam, lengkuas, termasuk terasi, cabe, dan bumbu penyedap lainnya sesuai dengan jenis makanan yang tercantum dalam daftar menu. Racikan sambel terdiri dari Cabe segar dan cukup tua dan bahan lainnya sesuai jenis sambel yang diinginkan diluar kebutuhan bumbu Kering, bersih, dengan merk dan nomor register beryodium Kualitas baik, tidak expire, dalam kemasan bersegel dan murni. Gas yang murnidan jika dipergunakan untuk masak tidak memedihkan mata. Bersih, tidak berbau, tidak berasa, tidak berwarna dan tidak mengandung logam berat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 108803);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62026351', 62026351, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'KELURAHAN P.UNTUNG JAWA - KEP. SERIBU', 'Pembayaran Gaji PPSU Kelurahan Pulau Untung Jawa', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Adm. Kepulauan Seribu (Kab.)', 3998999901, 'December 2025', 'APBD', 1, 1, '57', 'Tugas PPSU (Penanganan Prasarana dan Sarana Umum) adalah garda terdepan kebersihan dan pemeliharaan lingkungan di tingkat kelurahan, meliputi pembersihan jalan, saluran air, taman, PJU (Penerangan Jalan Umum) yang rusak, serta perbaikan ringan pada trotoar, kanstin, dan infrastruktur publik lainnya agar tetap berfungsi dan nyaman bagi warga, termasuk menindaklanjuti laporan kebersihan dari masyarakat', 'Spesifikasi tugas PPSU (Penanganan Prasarana dan Sarana Umum) adalah petugas di tingkat kelurahan yang bertanggung jawab atas pemeliharaan kebersihan, perbaikan jalan, saluran air, taman, serta Penerangan Jalan Umum (PJU), bertugas menjaga kenyamanan publik dan merespons kondisi darurat kecil di wilayahnya sesuai arahan Lurah, sering dikenal sebagai "pasukan oranye".', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 108804);
