INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62027971', 62027971, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'UNIT PENGELOLA KAWASAN PUSAT PENGEMBANGAN USAHA KECIL DAN MENENGAH SERTA PERMUKIMAN PULOGADUNG', 'Penyediaan Jasa Petugas Keamanan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 2174894683, 'December 2025', 'BLUD', 1, 1, '1 Kegiatan', 'Penyediaan Jasa Petugas Keamanan sebanyak 31 orang x 13 bulan', '1. Persyaratan Kualifikasi Administrasi/Legalitas meliputi : a. Warga Negara Indonesia b. Diutamakan memiliki Kartu Tanda Penduduk (KTP) dan Kartu Keluarga (KK) Provinsi DKI Jakarta dengan melampirkan KTP dan KK; c. Berusia paling sedikit 18 tahun dan maksimal 56 tahun terhitung mulai tanggal kontrak; d. Dapat membaca dan menulis dengan baik; e. Melampirkan Nomor Pokok Wajib Pajak (NPWP); f. Pendidikan terakhir minimal SLTA/sederajat dibuktikan dengan melampirkan Ijazah Pendidikan terakhir; g. Khusus Jasa Tenaga Keamanan wajib melampirkan Kartu Tanda Anggota (KTA) Satpam yang masih berlaku; h. Melampirkan fotocopy buku rekening Bank DKI; i. Melampirkan Surat Lamaran yang ditujukan kepada Pejabat Pembuat Komitmen Unit Pengelola Kawasan Pusat Pengembangan Usaha Kecil dan Menengah serta Permukiman Pulogadung; j. Melampirkan Surat Pernyataan yang menyatakan tidak dikenakan sanksi daftar hitam, tidak dalam pengawasan pengadilan dan/atau sedang menjalani sanksi pidana, dan tidak berstatus Aparatur Sipil Negara, kecuali yang bersangkutan mengambil cuti di luar tanggungan Negara; k. Melampirkan Surat Penawaran dan Dokumen Penawaran yang ditujukan kepada Pejabat Pengadaan Barang/Jasa Unit Pengelola Kawasan Pusat Pengembangan Usaha Kecil dan Menengah serta Permukiman Pulogadung l. Melampirkan Surat Pakta Integritas yang ditanda tangani diatas materai Rp. 10.000,- m. Melampirkan Form Isian Kualifikasi Penyedia Perorangan 2. Persyaratan Kualifikasi Teknis meliputi kemampuan untuk memenuhi kebutuhan Jasa Lainnya dan diutamakan yang telah berkontrak sebagai Tenaga Keamanan Unit Pengelola Kawasan Pusat Pengembangan Usaha Kecil dan Menengah serta Permukiman Pulogadung dibuktikan dengan melampirkan kontrak sebelumnya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 108886);
