INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62003138', 62003138, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli Data Quality Assurance Officer Pengolahan Data Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 42570000, 'June 2026', 'APBD', 1, 1, '1 orang x 6 bulan', 'Melakukan cleansing dan filterisasi data untuk memangkas informasi yang tidak relevan Identifikasi, analisis, dan interpretasikan tren atau pola dalam kumpulan data yang kompleks Mengembangkan atau menyesuaikan program metodologi, model untuk analisis dan ilustrasi data Menggunakan kompetensi yang dimiliki (pemprograman komputer, statistik) dalam proses analisis Membuat dan mengembangkan model statistika sebagai basis analisa data Membuat dokumen/instrumen kualitas data Bertanggung jawab atas proses uji kualitas data seperti PES dan DQA. Berperan aktif dalam melakukan pendampingan dan pelatihan terhadap kader dasawisma Melakukan pendampingan terkait sosialisasi pendataan keluarga satu pintu Berkoordinasi dengan tim tenaga ahli pengembangan sistem dalam memastikan validasi pada setiap pertanyaan dalam aplikasi.', 'Pendidikan terakhir S1 Jurusan Statistik/ Ilmu Statistik terapan lainya (Ekonometri, Psikometri,Biostatistik, Epidemilogi) IPK min 3.0 (PTS) /2.75 (PTN); Memiliki pengalaman kerja minimal 3 tahun di bidang pengolahan data Memiliki pengalaman mengerjakan manajemen data Memiliki logika yang kuat dalam menganalisa data dan menyajikannya secata tepat Menguasai pengetahuan dalam mengunakan aplikasi statistik (SPSS, STATA, SAS, dll) Menguasai pengetahuan dalam mengunakan aplikasi geospasial (Arch GIS, Quantum GIS, gVISG, dll) Memahami konsep database Mampu menyajikan data dengan format yang tepat Diutamakan pernah mengikuti pelatihan ISO 27001', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 109047);
