INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62005207', 62005207, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PANTI SOSIAL BINA LARAS HARAPAN SENTOSA 2', 'Pengadaan Jasa Tenaga Keamanan Panti Sosial Bina Laras Harapan Sentosa 2 Tahun 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Timur (Kota)', 701578930, 'November 2025', 'APBD', 1, 1, '10 Orang x 13 Bulan', 'Ruang lingkup pekerjaan meliputi: 1. Menyelenggarakan keamanan, kenyamanan dan ketertiban di lingkungan kerja; 2. Melakukan pengawasan setiap waktu termasuk malam, penjagaan sarana prasarana, WBS, aset dan lingkungan kantor; 3. Dalam kondisi darurat dapat melakukan koordinasi dengan aparat setempat; 4. Membantu menertibkan parkir kendaraan; 5. Mencatat dan dan mengawasi keluar masuk tamu, pegawai, Warga Binaan Sosial (WBS) ataupun kendaraaan yang keluar masuk; 6. Mengidentifikasi tamu yang datang ke panti dan mengarahkan mengisi buku tamu; 7. Melakukan pendampingan bagi WBS terhadap kebersihan dan kerapian asrama dan lingkungan sekitar dalam mengikuti kegiatan sehari-hari dalam mengikuti kegiatan sehari di panti seperti activity daily living, ibadah, makan, mandi, piket, apel, kerja bakti, belajar dan sebagainya; 8. Membantu mengerahkan WBS untuk mengikuti kegiatan; 9. Melaksanakan tugas kedinasan lainnya baik lisan maupun tulisan yang masih menjadi bagian pekerjaannya. 10.Mencatat dan melaporkan kinerja harian secara online setiap akhir bulan berjalan dan menyerahkan dokumen cetak ke Ka Sub Bagian Tata Usaha maksimal tanggal 5 (lima) setiap bulannya', 'spesifikasi teknis terdiri dari: - Warga Negara Indonesia; - Bertakwa kepada Tuhan Yang Maha Esa dan taat kepada Pancasila, Undang-Undang Dasar Tahun 1945 serta Negara Kesatuan Republik Indonesia; - Berjenis kelamin perempuan atau laki-laki dengan usia paling rendah 18 tahun 0 bulan 0 hari dan paling tinggi 56 tahun 0 bulan 0 hari pada tanggal 1 Januari 2025 (sesuai Keputusan Gubernur Nomor 1095 Tahun 2022); - Pendidikan minimal lulusan SLTA/sederajat atau SLTP/sederajat yang sedang mengikuti Paket C, dibuktikan dengan surat keterangan; - Sanggup bekerja penuh waktu; - Bersedia ditugaskan di lingkungan kerja Panti Sosial Bina Laras Harapan Sentosa 2 dan diluar jam kerja;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 109215);
